'use strict';
// Register canonical USD prices before installing the new, already-denominated world decisions.
Economy.install();WorldTimeline.install();
const EpochUI=(()=>{
 const num=n=>(Number(n)||0).toLocaleString('en-US',{maximumFractionDigits:0}),labels={expedition:'ค่าคุ้มครองและบำรุงอุปกรณ์สมาคม',housing:'ที่พัก / บำรุงถิ่น',food:'อาหารและแหล่งดำรงชีวิต',utilities:'น้ำ พลังงาน และการบำรุง',health:'สุขภาพและการดูแล',transport:'การเดินทาง',needs:'ของจำเป็น'};
 function panel(s){const e=Economy.ensure(s),w=WorldTimeline.impact(s),y=Economy.annual(s),known=w.threats.filter(t=>t.phase==='active'||s.worldTimeline.office===t.faction),threat=known[0];return `<section class="epoch-panels">${RaceDrives.cashless(s)?`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">แหล่งถิ่นที่เลี้ยงร่าง · ปี ${y.year}</span><strong>${Math.round(s.raceDrives.resource)} <small>/100</small></strong><span>${esc(SpeciesSociety.profile(s).res)}</span><small>เงินจากการแลกเปลี่ยน ${num(s.gold)} ทอง · ดูวิถี ↗</small></button>`:`<button class="panel money-overview" id="openEconomy"><span class="eyebrow">เงินส่วนตัว · 1 ทอง = 1 USD</span><strong>${num(s.gold)} <small>ทอง</small></strong><span>ปี ${y.year} · รายรับสุทธิสะสม ${num(y.income)} ทอง</span><small>ภาระและการใช้จ่ายปีนี้ ${num(y.cost)} ทอง${e.debt?' · หนี้ '+num(e.debt):''} · ดูบัญชีรายปี ↗</small>${Engine.biological(s)<16?'<small>ทุนของ'+esc(s.race===0?'ครอบครัว':SpeciesSociety.profile(s).group)+'แยกจากเงินที่มอบให้คุณ</small>':''}</button>`}<button class="panel epoch-overview ${w.severity>.4?'epoch-danger':''}" id="openWorldYear"><span class="eyebrow">โลกที่เกิดขึ้นในขณะนี้</span><strong>ปี ${w.year}</strong><span>${esc(threat?.name||w.omen)}</span><small>ราคาท้องถิ่น ${Math.round(w.price*100)}% · อ่านข่าวปีนี้ ↗</small></button></section>`}
 function bind(){if($('#openEconomy'))$('#openEconomy').onclick=money;if($('#openWorldYear'))$('#openWorldYear').onclick=world}
 function refresh(view){save();clock.reset();render();view()}
 function money(){const s=state,e=Economy.ensure(s),q=Economy.quote(s),y=Economy.annual(s),locked=s.dead||!s.accepted||s.outcome||s.calendar?.pending||Engine.biological(s)<16;modal(`<section class="epoch-dialog"><span class="eyebrow">บัญชีชีวิต · ปี ${y.year} · 1 ทอง = 1 USD</span><h2>เงินส่วนตัว ${num(s.gold)} ทอง</h2><p class="money-explainer">สรุปเป็นรายปี รายรับและภาระทยอยเกิดทุกสามเดือนตามปฏิทินจริงของโลก เงินครอบครัวไม่ได้เป็นเงินพร้อมใช้ของคุณ</p><div class="economy-totals"><div><small>รายรับสุทธิสะสมปีนี้</small><b>${num(y.income)}</b></div><div><small>ภาระและการใช้จ่ายปีนี้</small><b>${num(y.cost)}</b></div><div><small>ค่าครองชีพตามแผนต่อปี</small><b>${num(q.monthly*12)}</b></div><div><small>หนี้ส่วนตัว</small><b class="money-loss">${num(e.debt)}</b></div><div><small>${s.race!==0?'ทุนส่วนรวมของ'+esc(SpeciesSociety.profile(s).group):'เงินสำรองของครอบครัว'}</small><b>${num(e.familyFund)}</b></div><div><small>ค่าจ้างเต็มปีโดยประมาณ</small><b>${Adventures.isCareer(s)?'รับตามงานสำเร็จ':num(Economy.salary(s))}</b></div></div>${e.familyArrears>0?`<p class="economy-warning">บ้านยังขาดค่าใช้จ่าย ${num(e.familyArrears)} ทอง · แยกจากหนี้ส่วนตัว</p>`:''}<h3 class="year-ledger-title">ปี ${y.year} · รับและจ่ายจริงสะสม</h3><dl class="account-lines"><div><dt>รายรับงานก่อนภาษี</dt><dd>+${num(y.gross)}</dd></div><div><dt>ภาษีจำลอง</dt><dd>−${num(y.tax)}</dd></div><div><dt>ส่วนที่บ้านมอบให้จริง</dt><dd>+${num(y.support)}</dd></div><div><dt>รับอื่นและขายทรัพย์สิน</dt><dd>+${num(y.otherIncome)}</dd></div><div><dt>ค่าครองชีพและบิล</dt><dd>−${num(y.expenses)}</dd></div><div><dt>ซื้อของ เสบียง และภาระอื่น</dt><dd>−${num(y.otherSpend)}</dd></div><div><dt>ดอกเบี้ยหนี้ที่เกิดขึ้น</dt><dd>−${num(y.interest)}</dd></div><div><dt>คืนเงินต้น</dt><dd>−${num(y.principal)}</dd></div><div><dt>ค่าใช้จ่ายที่เงินยังไม่ถึง</dt><dd>${num(y.shortfall)}</dd></div></dl><p class="annual-budget-note">ค่าครองชีพเป็นงบเต็มปี ยอดสะสมข้างบนคิดเฉพาะช่วงที่ผ่านไป หนี้ค้างมีดอกเบี้ย 18% ต่อปี ส่วนที่เกินวงเงินไม่ได้ยืมเพิ่มและทำให้บางบริการต้องเลื่อน การขายทรัพย์สินเป็นเงินรับครั้งเดียว</p>${RaceDrives.cashless(s)?'<p class="money-explainer">ร่างและถิ่นนี้ใช้แหล่งดำรงชีวิตตามธรรมชาติ ไม่มีเงินเดือนหรือค่าเช่าเมือง งานที่รับยังมีต้นทุนแหล่งถิ่น</p>':''}${Economy.canPatron(s)?`<button class="secondary" id="requestPatron" ${locked?'disabled':''}>คุยเรื่องส่วนแบ่งจากทุนเดิมของกลุ่ม ${num(Economy.patronAmount(s))} ทอง →</button>`:''}<h3>เลือกภาระที่รับไหวในหนึ่งปี</h3><div class="epoch-selectors"><label>แผนชีวิต<select id="economyBudget" ${locked?'disabled':''}>${[['lean','ประหยัด · ลดส่วนที่ลดได้ 18%'],['standard','ใช้ตามความจำเป็น'],['comfort','สะดวกสบาย · เพิ่มงบ 40%']].map(([id,label])=>`<option value="${id}" ${e.budget===id?'selected':''}>${label}</option>`).join('')}</select></label><label>ที่พัก<select id="economyHousing" ${locked||q.native||s.spending.home.owned?'disabled':''}><option value="family" ${e.housing==='family'?'selected':''}>แบ่งค่าใช้จ่ายในที่พักร่วม</option><option value="rent" ${e.housing==='rent'?'selected':''}>เช่าที่พักแยก</option>${Adventures.ensure(s).member&&!s.children?`<option value="guild" ${e.housing==='guild'?'selected':''}>ที่พักรวมของสมาคม</option>`:''}</select></label></div><dl class="account-lines">${q.rows.map(r=>`<div><dt>${esc(s.race!==0?SpeciesSociety.costLabel(s,r.id,labels[r.id]):labels[r.id])}</dt><dd>${num(r.monthly*12)} / ปี</dd></div>`).join('')}</dl><button class="secondary" id="economyHousingLevels">ที่พักห้าระดับและค่าบำรุง →</button><h3>หาเงินและจัดการภาระ</h3><div class="choices">${Economy.actions.map(a=>`<button class="choice" data-economy-action="${a.id}" ${locked||e.actionQuarter===s.calendar.count||RaceDrives.cashless(s)&&['shift','aid'].includes(a.id)?'disabled':''}><span><b>${a.name}</b><small>${a.description}</small></span></button>`).join('')}</div><p id="economyError" class="money-loss" role="status"></p><p class="money-explainer">รับงานเพิ่มหนึ่งครั้งต่อสามเดือน เงินเพิ่มต้องแลกด้วยกำลังและเวลาพัก</p><button class="secondary" id="economySpending">ใช้เงินและลงทุน →</button>${y.last?`<details><summary>ปีที่ปิดบัญชีแล้ว ${y.last.year}</summary><p>รายรับสุทธิ ${num(y.last.gross-y.last.tax+y.last.support+y.last.otherIncome)} ทอง · ค่าใช้จ่ายและดอกเบี้ย ${num(y.last.expenses+y.last.otherSpend+y.last.interest)} ทอง</p></details>`:''}<details><summary>รายการที่เกิดขึ้นแล้ว</summary>${e.history.map(h=>`<p><b>อายุ ${h.age} · ${esc(h.title)}</b><br>${esc(h.text)}</p>`).join('')}</details></section>`);$('#economyBudget').onchange=ev=>{if(Economy.setPlan(s,'budget',ev.target.value))refresh(money)};$('#economyHousing').onchange=ev=>{if(Economy.setPlan(s,'housing',ev.target.value))refresh(money)};document.querySelectorAll('[data-economy-action]').forEach(b=>b.onclick=()=>{if(Economy.action(s,b.dataset.economyAction))refresh(money);else $('#economyError').textContent='เงื่อนไขยังไม่ครบ หรือเงินส่วนตัวยังไม่พอ'});$('#economySpending').onclick=SpendingUI.open;$('#economyHousingLevels').onclick=HousingUI.open;if($('#requestPatron'))$('#requestPatron').onclick=()=>{const e=EVENTS.find(e=>e.familyEndowment);if(!locked&&Engine.eligible(s,e)){s.event={...Economy.decorate(s,e),context:WorldLore.context(s,s.calendar.count)};s.calendar.pending=true;$('#modal').close();save();render()}}}
 function offer(id){const s=state,event=EVENTS.find(e=>e.officeOnly===id);if(!event||s.dead||s.outcome||s.calendar.pending||!Engine.eligible(s,event))return;s.event={...WorldTimeline.decorate(s,event),context:WorldLore.context(s,s.calendar.count)};s.calendar.pending=true;$('#modal').close();save();render()}
 function world(){const s=state,w=WorldTimeline.ensure(s),report=WorldTimeline.impact(s),known=report.threats.filter(t=>t.phase==='active'||w.office===t.faction);modal(`<section class="epoch-dialog"><span class="eyebrow">พงศาวดารที่คุณรับรู้ในชีวิตนี้</span><h2>ปี ${report.year}</h2><h3>${esc(report.omen)}</h3><p>${esc(report.news)}</p><div class="epoch-chronicle">${known.map(a=>`<article class="${a.phase==='active'&&a.mode==='attack'?'epoch-danger':''}"><small>ข่าวที่มาถึงในปี ${report.year}</small><h3>${esc(a.name)}</h3><p>${esc(a.phase==='warning'?'กองทัพฝ่ายของคุณเริ่มเตรียมกำลัง สภารอฟังว่าจะใช้กำลังหรือเจรจา':a.mode==='peace'?'การเจรจาเปิดทางให้หลายฝ่ายกลับมาพูดคุย':a.mode==='delay'?'กองทัพหยุดเพื่อจัดการภาระในดินแดน':a.text)}</p></article>`).join('')}</div><h3>สิ่งที่อาณาจักรเผชิญในปีนี้</h3><div class="epoch-regions">${KINGDOMS.map((k,i)=>{const r=WorldTimeline.impact(s,i);return `<div class="${i===s.kingdom?'current':''}"><b>${esc(k[0])}${i===s.kingdom?' · คุณอยู่ที่นี่':''}</b><span>ราคา ${Math.round(r.price*100)}% · งาน ${Math.round(r.jobs*100)}%</span><small>${r.severity>.5?'แนวรบและการอพยพ':r.severity>.15?'เสบียงและการค้าได้รับผล':'ผลกระทบทางอ้อม'}</small></div>`}).join('')}</div><h3>เรื่องที่ผ่านมาระหว่างชีวิตนี้</h3>${w.history.filter(h=>h.year<=report.year).slice(0,16).map(h=>`<p><b>ปี ${h.year}</b> · ${esc(h.title)} · ${esc(KINGDOMS[h.realm][0])}</p>`).join('')||'<p>ยังไม่มีข่าวที่บันทึกไว้</p>'}<details><summary>บทบาทที่คุณอาจรับผิดชอบในสังคม</summary><p>ผู้ที่โตเต็มวัย มีผลงานและได้รับความไว้ใจสามารถขอรับบทบาทดูแลส่วนรวมได้</p>${WorldTimeline.offices.map(o=>{const e=EVENTS.find(e=>e.officeOnly===o.id);return e&&Engine.eligible(s,e)?`<button class="secondary" data-world-office="${o.id}">${esc(o.name)}</button>`:''}).join('')}</details></section>`);document.querySelectorAll('[data-world-office]').forEach(b=>b.onclick=()=>offer(b.dataset.worldOffice))}

 return {panel,bind,money,world,offer};
})();
